\begin{align*}
P_A(v^*) &= (1 - p_f) \times \prod_{i \in D_A(v^*)} P_A(i), \\
P_B(v^*) &= (1 - p_f) \times \prod_{i \in D_B(v^*)} P_B(i) = (1 - p_f) \times P_B(d) \times \prod_{i \in D_A(v^*)} P_B(i).
\end{align*}

\begin{align*}
E[S_A] &= \sum_{v \in \mathcal{T}} P_A(v), \\
E[S_B] &= \sum_{v \in \mathcal{T}} P_B(v).
\end{align*}

\begin{align*}
E[S_B] &= \sum_{v \neq v^*} P_B(v) + P_B(v^*) \\
&= \sum_{v \neq v^*} P_A(v) + P_B(v^*) \\
&= \left( \sum_{v \in \mathcal{T}} P_A(v) - P_A(v^*) \right) + P_B(v^*) \\
&= E[S_A] - \left( P_A(v^*) - P_B(v^*) \right).
\end{align*}
